/** Account-scoped, server-owned support updates. No wallet state or credentials are stored here. */
const empty=()=>({notifications:[],unreadCount:0,total:0,page:1,pageSize:30,error:'',loading:false});
const uuid=/^[0-9a-f]{8}-[0-9a-f-]{27}$/i;
export function createSupportInbox({request,identity,onChange=()=>{},onNew=()=>{}}){
 let owner='',generation=0,state=empty(),busy=null,stop=null,initialized=false;const listeners=new Set();
 const emit=()=>{onChange();for(const fn of [...listeners])fn();};
 function current(){const next=String(identity()||'');if(next!==owner){owner=next;generation++;state=empty();busy=null;initialized=false;emit();}return owner;}
 function snapshot(){current();return {...state,notifications:state.notifications.map(n=>({...n}))};}
 async function send(operation,payload={}){const actor=current(),epoch=generation;if(!actor)return {ok:false,code:'AUTH_REQUIRED',message:'Sign in to see your support updates.'};try{const result=await request(operation,payload);if(current()!==actor||generation!==epoch)return {ok:false,code:'ACCOUNT_CHANGED'};return result;}catch{return {ok:false,code:'UNAVAILABLE',message:'Support updates could not refresh. Try again when connected.'};}}
 async function refresh(page=1){current();if(!owner)return snapshot();if(busy)return busy;const actor=owner,epoch=generation;state.loading=true;emit();const work=(async()=>{const result=await send('list',{page,pageSize:30});if(owner!==actor||generation!==epoch)return snapshot();if(result?.ok&&Array.isArray(result.notifications)&&Number.isSafeInteger(result.unreadCount)&&result.unreadCount>=0&&result.notifications.every(n=>uuid.test(n.id||'')&&uuid.test(n.caseId||'')&&typeof n.body==='string'&&n.body.length<=600&&typeof n.title==='string'&&n.title.length<=120)){
 const known=new Set(state.notifications.map(n=>n.id)),previous=initialized;const fresh=result.notifications.filter(n=>!n.readAt&&!known.has(n.id));
 const rows=page>1?[...state.notifications,...result.notifications]:result.notifications;state={notifications:[...new Map(rows.map(n=>[n.id,n])).values()],unreadCount:result.unreadCount,total:result.total,page:result.page,pageSize:result.pageSize,error:'',loading:false};initialized=true;if(previous&&fresh.length&&page===1)onNew(fresh[0]);
 }else{state.loading=false;state.error=result?.message||'Support updates could not refresh. Try again.';}emit();return snapshot();})();busy=work;try{return await work;}finally{if(busy===work)busy=null;}}
 async function readCase(caseId,notificationId){if(!uuid.test(caseId||''))return {ok:false,message:'This case is unavailable.'};const actor=current(),epoch=generation;const result=await send('case',{caseId});if(!result?.ok)return result||{ok:false};if(notificationId){const ack=await send('read',{notificationId});if(ack?.ok){state.notifications=state.notifications.map(n=>n.id===notificationId?{...n,readAt:n.readAt||new Date().toISOString()}:n);await refresh();}}if(current()!==actor||generation!==epoch)return {ok:false,code:'ACCOUNT_CHANGED',message:'Sign in to open your support updates.'};return result;}
 function start(){if(stop)return stop;const update=()=>{if(!globalThis.document||document.visibilityState!=='hidden')void refresh();};const timer=setInterval(update,15000);timer.unref?.();globalThis.document?.addEventListener('visibilitychange',update);update();stop=()=>{clearInterval(timer);globalThis.document?.removeEventListener('visibilitychange',update);stop=null;};return stop;}
 return {get snapshot(){return snapshot();},refresh,readCase,start,subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn);},get signedIn(){return !!current();}};
}
